class Solution:
    def chainFollow(self, A: List[str], B: List[str]) -> List[str]:
        A, B = [A], [B]
        stack = [(A, B)]
        res = []
        while stack:
            a, b = stack.pop()
            if a == b:
                res.append(a)
            if a[0] == 'a':
                stack.append((a[1], b))
            else:
                stack.append((a[0], b))
        return ','.join(res)
